import{_ as t,o,c as a,a2 as i}from"./chunks/framework.BXzK3EA4.js";const r="/assets/ab1.fwbJ3rcW.png",s="/assets/ab2.BuU1fYO_.PNG",l="/assets/ab3.CG-8VUx6.png",n="/assets/ab4.1CVnKg_H.png",c="/assets/ab5.t0FfAL6I.png",A=JSON.parse('{"title":"AliceBlue","description":"","frontmatter":{},"headers":[],"relativePath":"connect-brokers/brokers/aliceblue.md","filePath":"connect-brokers/brokers/aliceblue.md"}'),d={name:"connect-brokers/brokers/aliceblue.md"};function u(p,e,h,g,f,b){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="aliceblue" tabindex="-1">AliceBlue <a class="header-anchor" href="#aliceblue" aria-label="Permalink to &quot;AliceBlue&quot;">​</a></h1><p>Tradeboard provides seamless integration with AliceBlue, enabling you to connect your trading strategies with AliceBlue’s brokerage services. Follow this guide to set up your AliceBlue broker account with Tradeboard.</p><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><p>Before proceeding, ensure you have the following:</p><ul><li>An active AliceBlue trading account.</li><li>Access to the AliceBlue ANT website.</li><li>Tradeboard installed and configured on your local machine.</li></ul><h3 id="steps-to-create-the-aliceblue-api-secret-key" tabindex="-1">Steps to Create the AliceBlue API Secret Key <a class="header-anchor" href="#steps-to-create-the-aliceblue-api-secret-key" aria-label="Permalink to &quot;Steps to Create the AliceBlue API Secret Key&quot;">​</a></h3><figure><img src="'+r+'" alt=""><figcaption></figcaption></figure><ol><li><strong>To register as a Individual trader/Vendor,</strong><ul><li>Navigate to the <a href="https://a3.aliceblueonline.com/" target="_blank" rel="noreferrer">https://a3.aliceblueonline.com/</a></li><li>Select <strong>Login as Individual Trader</strong></li><li>Enter your credentials to log in.</li></ul></li></ol><figure><img src="'+s+'" alt=""><figcaption></figcaption></figure><ol start="2"><li><strong>Access My Apps</strong></li></ol><ul><li>On the top right corner, click on <strong>Create App</strong>.</li></ul><figure><img src="'+l+'" alt=""><figcaption></figcaption></figure><ul><li>Fill up the Mandatory Fields.</li><li>Save it</li></ul><figure><img src="'+n+'" alt=""><figcaption></figcaption></figure><ul><li>Fill up the Ip address , select the IP Type from the drop down and submit it.</li></ul><figure><img src="'+c+`" alt=""><figcaption></figcaption></figure><ol><li><strong>Generate API Key</strong><ul><li>If you don’t already have an API key, generate a new one by following the on-screen instructions.</li><li>Note down the <strong>App Code</strong> and the <strong>API Secret Key</strong>, as both are required for configuring the <code>.env</code> file.</li></ul></li></ol><h3 id="configuring-the-env-file" tabindex="-1">Configuring the <code>.env</code> File <a class="header-anchor" href="#configuring-the-env-file" aria-label="Permalink to &quot;Configuring the \`.env\` File&quot;">​</a></h3><p>AliceBlue uses an OAuth redirect login. Tradeboard sends the <strong>App Code</strong> of the app you created to <code>https://ant.aliceblueonline.com/?appcode=...</code>, and AliceBlue calls back with an <code>authCode</code> and <code>userId</code>. Tradeboard then signs <code>userId + authCode + apiSecret</code> and exchanges the result for a session.</p><p>So <code>BROKER_API_KEY</code> holds the <strong>App Code</strong> of your app, not your AliceBlue login user ID. Below is a sample configuration for the <code>.env</code> file:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># AliceBlue Broker Configuration</span></span>
<span class="line"><span>BROKER_API_KEY = &#39;your_app_code_here&#39;</span></span>
<span class="line"><span>BROKER_API_SECRET = &#39;your_api_secret_here&#39;</span></span>
<span class="line"><span>REDIRECT_URL = &#39;http://127.0.0.1:5000/aliceblue/callback&#39;</span></span></code></pre></div><p>Replace <code>your_app_code_here</code> with the App Code shown for your AliceBlue app and <code>your_api_secret_here</code> with the generated API secret key.</p><h4 id="important-notes" tabindex="-1">Important Notes <a class="header-anchor" href="#important-notes" aria-label="Permalink to &quot;Important Notes&quot;">​</a></h4><ul><li>Ensure that your <strong>API Secret Key</strong> is stored securely and is not shared publicly.</li><li>The <strong>REDIRECT_URL</strong> should match the one registered with your API application.</li></ul><p>Follow these steps to integrate AliceBlue with Tradeboard successfully. If you encounter any issues, refer to the AliceBlue API documentation for further assistance.</p><h3 id="supported-exchanges" tabindex="-1">Supported Exchanges <a class="header-anchor" href="#supported-exchanges" aria-label="Permalink to &quot;Supported Exchanges&quot;">​</a></h3><p>Tradeboard reads this plugin&#39;s exchange list from <code>broker/aliceblue/plugin.json</code> and serves it to the app, so symbol search, the Strategy Builder and the tools pages only offer what the plugin actually handles.</p><ul><li><strong>Tradable:</strong> <code>NSE</code>, <code>BSE</code>, <code>NFO</code>, <code>BFO</code>, <code>CDS</code>, <code>BCD</code>, <code>MCX</code></li><li><strong>Index feeds:</strong> <code>NSE_INDEX</code>, <code>BSE_INDEX</code></li></ul>`,28)])])}const m=t(d,[["render",u]]);export{A as __pageData,m as default};
